from harness import *
import datetime as dt
async def C(pg,fn,*a): return await T(pg,"call("+",".join([json.dumps(fn)]+[json.dumps(x) for x in a])+")")
async def M(pg,code): return await pg.evaluate("c=>__LIFE_SIM_TEST__.mutate(c)",code)
async def go(pg,d,m=600):
    prev=(dt.date.fromisoformat(d)-dt.timedelta(days=1)).isoformat(); await T(pg,f"setClock('{prev}',1435)"); await T(pg,f"advanceMinutes({5+m})")
async def main():
  async with async_playwright() as p:
    b=await p.chromium.launch(executable_path=CHROME); pg=await new_page(b); await new_life(pg,dob='2010-03-10'); await T(pg,"setAge(17)"); await T(pg,"setMoney(3000,0,0)")
    await go(pg,'2027-09-20'); s=await st(pg); check('V1: senior year = Grade 12 (Sept 2027)', 'Grade 12' in s['school']['grade'], s['school']['grade'])
    await go(pg,'2027-09-25'); s=await st(pg); check('V1/67: counselor meeting in semester 1 of senior year', any(e['type']=='counselor' for e in s['events']))
    tl=await C(pg,'seniorTimeline'); check('V1/67: applications open at the start of semester 2 for 2 months', (dt.date.fromisoformat(tl['windowClose'])-dt.date.fromisoformat(tl['windowOpen'])).days==60 and tl['windowOpen']==tl['a']['sem2Start'])
    check('V1/68: the loan window is in the middle of semester 2', tl['windowOpen']<tl['loanFrom']<tl['decisions'])
    for i in range(12): await C(pg,'addToList',f'uni{i}')
    s=await st(pg); check('V1: the school list holds at most 10', len(s['uniApps']['list'])==10)
    await C(pg,'applyTo','uni0'); s=await st(pg); check('V1: cannot apply before the window opens', not s['uniApps']['applied'])
    await M(pg,"S.uniApps.list=['uni3','uni6','uni9','uni11','uni0','uni1','uni2','uni4','uni5','uni7'];S.inventoryItems=S.inventoryItems.filter(i=>i.key!=='laptop')"); await C(pg,'addItem','laptop','QC')
    await go(pg,addd:=(dt.date.fromisoformat(tl['windowOpen'])+dt.timedelta(days=2)).isoformat(),1000)
    e0=(await st(pg))['uniApps']['essay']
    for i in range(2): await C(pg,'writeEssay')
    s=await st(pg); check('V1: working on the essay raises its quality', s['uniApps']['essay']>e0)
    for i in [3,6,9,11,0,1,2,4,5,7,8]: await C(pg,'applyTo',f'uni{i}')
    s=await st(pg); check('V1/67: up to 10 applications (the 11th is refused)', len(s['uniApps']['applied'])==10, len(s['uniApps']['applied']))
    await C(pg,'applyLoan'); s=await st(pg); check('V1/68: the loan cannot be applied for outside its window', not s['uniApps'].get('loan'))
    await go(pg,(dt.date.fromisoformat(tl['loanFrom'])+dt.timedelta(days=3)).isoformat(),1000); await C(pg,'applyLoan'); s=await st(pg)
    check('V1/68: interest-free student loan approved in mid-semester 2', s['uniApps']['loan'] and s['uniApps']['loan']['interest']==0)
    await M(pg,"S.school.subjects.forEach(x=>x.score=99)"); rk=await C(pg,'classRank'); check('V1/68: top grades → top 3 in class', rk['rank']<=3, rk)
    f=await C(pg,'funding','uni0'); check('V1/68: merit scholarship for the top 3 of the class', f['scholarship']>=10000, f)
    await go(pg,tl['decisions'],900); await T(pg,"advanceMinutes(1500)"); s=await st(pg)
    dec=s['uniApps']['decisions']; check('V1/67: decisions arrive for every application', len(dec)==10, len(dec))
    check('V1/67: with a laptop, decisions come by email', any('emails from admissions' in l['text'] for l in s['log'][:20]))
    check('V1/67: an acceptance → family celebration', any('celebration' in l['title'].lower() for l in s['log'][:20]))
    acc=[k for k,v in dec.items() if v=='Accepted']; await C(pg,'enroll',acc[0]); s=await st(pg); check('V1: enroll at a school that accepted you', s['uniApps']['choice']==acc[0])
    # graduation from high school, then university year 1
    await go(pg,'2028-06-20'); await T(pg,"advanceMinutes(2000)"); s=await st(pg); check('V1: high school ends after Grade 12', s['school'] is None)
    nav=await pg.evaluate("document.body.innerText"); check('V1: Education stays visible after high school (University)', 'Education' in nav)
    await go(pg,'2028-09-05'); await T(pg,"advanceMinutes(1500)"); s=await st(pg)
    check('V1: university starts in the fall (year 1) and tuition is charged', s.get('uni',{}).get('enrolled') and s['uni']['year']==1 and any(l['title']=='Tuition' for l in s['log'][:30]), s.get('uni'))
    await T(pg,"openTab('school')"); txt=await pg.inner_text('#panel-host'); check('V1: University panel shows school, year, GPA', 'GPA' in txt and 'Year' in txt)
    g0=s['uni'].get('semStudy',0); await T(pg,"setClock('2028-09-10',1000)"); await C(pg,'uniStudy'); s=await st(pg); check('V1/V3: studying counts toward this semester\'s GPA', s['uni']['semStudy']>g0)
    # housing
    await M(pg,"S.money=5000"); await C(pg,'moveTo','dorm'); s=await st(pg); check('V1/66: enrolled students can move into a dorm', s['housing']['type']=='dorm')
    m0=s['money']; await go(pg,'2028-10-01',300); s=await st(pg); check('V1/66: rent is charged on the 1st of the month', s['money']<m0, (m0,s['money']))
    await C(pg,'moveTo','apartment'); await M(pg,"S.money=0"); await go(pg,'2028-11-01',300); await go(pg,'2028-12-01',300); s=await st(pg)
    check('V1/66: two missed months → evicted back to your parents', s['housing']['type']=='parents', s['housing'])
    await M(pg,"S.uni.year=4;S.uni.yearKey=2031"); await go(pg,'2032-09-10'); await T(pg,"advanceMinutes(1500)"); s=await st(pg)
    check('V1: after 4 years → university degree', s['education'].get('degree') and not s['uni']['enrolled'], s.get('uni'))
    check('V1: no JS errors', not pg.errs, pg.errs[:3]); await pg.close()
    # rejected everywhere → family reaction; under 18 cannot move out
    pg=await new_page(b); await new_life(pg,dob='2010-03-10'); await T(pg,"setAge(16)"); await C(pg,'moveTo','apartment'); s=await st(pg)
    check('V1/66: no moving out before 18', s.get('housing',{}).get('type','parents')=='parents')
    await T(pg,"setAge(17)"); await T(pg,"setMoney(1000,0,0)"); await go(pg,'2027-09-20'); tl=await C(pg,'seniorTimeline')
    await M(pg,"S.school.subjects.forEach(x=>x.score=55);S.uniApps=null;S.family.closeness=80"); await go(pg,(dt.date.fromisoformat(tl['windowOpen'])+dt.timedelta(days=1)).isoformat(),1000)
    for i in [0,1]: await C(pg,'addToList',f'uni{i}'); await C(pg,'applyTo',f'uni{i}')
    await go(pg,tl['decisions'],900); await T(pg,"advanceMinutes(1500)"); s=await st(pg)
    check('V1/67: rejected everywhere → family reacts (comfort with a close family)', all(v!='Accepted' for v in s['uniApps']['decisions'].values()) and any(l['title']=='No acceptances' and 'together' in l['text'] for l in s['log'][:20]))
    check('V1 (rejections): no JS errors', not pg.errs, pg.errs[:3]); await b.close()
asyncio.run(main())
